  1→import { useState } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { Switch } from "@/components/ui/switch";
  8→import { Label } from "@/components/ui/label";
  9→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
 10→import { toast } from "sonner";
 11→import { Copy, Mail, Check, ChevronDown, Info } from "lucide-react";
 12→
 13→const EmailInboxCard = () => {
 14→  const { user, profile, refreshProfile } = useAuth();
 15→  const [togglingEmail, setTogglingEmail] = useState(false);
 16→  const [copied, setCopied] = useState(false);
 17→  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
 18→
 19→  const handleCopyInbox = () => {
 20→    if (profile?.inbox_email) {
 21→      navigator.clipboard.writeText(profile.inbox_email);
 22→      setCopied(true);
 23→      toast.success("Inbox email copied to clipboard.");
 24→      setTimeout(() => setCopied(false), 2000);
 25→    }
 26→  };
 27→
 28→  const handleToggleEmail = async (checked: boolean) => {
 29→    if (!user) return;
 30→    setTogglingEmail(true);
 31→    const { error } = await supabase
 32→      .from("profiles")
 33→      .update({ email_enabled: checked })
 34→      .eq("user_id", user.id);
 35→    if (error) {
 36→      toast.error(error.message);
 37→    } else {
 38→      await refreshProfile();
 39→      toast.success(checked ? "Email enabled" : "Email disabled");
 40→    }
 41→    setTogglingEmail(false);
 42→  };
 43→
 44→  return (
 45→    <Card className="overflow-hidden">
 46→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 47→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 48→          <Mail className="h-4.5 w-4.5 text-primary" />
 49→        </div>
 50→        <div>
 51→          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
 52→          <p className="text-xs text-muted-foreground">
 53→            Forward resumes here to auto-add them to your jobs.
 54→          </p>
 55→        </div>
 56→      </div>
 57→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 58→        {profile?.inbox_email ? (
 59→          <>
 60→            <div>
 61→              <Label className="text-xs text-muted-foreground mb-1.5 block">Your fallback inbox</Label>
 62→              <div className="flex items-center gap-2">
 63→                <Input
 64→                  value={profile.inbox_email}
 65→                  readOnly
 66→                  className="font-mono text-sm bg-accent/50"
 67→                />
 68→                <Button
 69→                  variant="outline"
 70→                  size="icon"
 71→                  onClick={handleCopyInbox}
 72→                  title="Copy"
 73→                  className="shrink-0"
 74→                >
 75→                  {copied ? (
 76→                    <Check className="h-4 w-4 text-primary" />
 77→                  ) : (
 78→                    <Copy className="h-4 w-4" />
 79→                  )}
 80→                </Button>
 81→              </div>
 82→            </div>
 83→            <p className="text-xs text-muted-foreground">
 84→              Each job also gets its own unique inbox email. Check the job detail page to copy it.
 85→            </p>
 86→          </>
 87→        ) : (
 88→          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
 89→            No inbox email assigned yet.
 90→          </div>
 91→        )}
 92→        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
 93→          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
 94→            Email ingestion enabled
 95→          </Label>
 96→          <Switch
 97→            id="email-toggle"
 98→            checked={profile?.email_enabled ?? true}
 99→            onCheckedChange={handleToggleEmail}
100→            disabled={togglingEmail}
101→          />
102→        </div>
103→
104→        {/* How it works */}
105→        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
106→          <CollapsibleTrigger asChild>
107→            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
108→              <span className="flex items-center gap-1.5">
109→                <Info className="h-3.5 w-3.5" />
110→                How email ingestion works
111→              </span>
112→              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
113→            </Button>
114→          </CollapsibleTrigger>
115→          <CollapsibleContent className="pt-2">
116→            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2">
117→              <p><strong>Per-job inbox:</strong> Each job gets a unique email address. Forward resumes to it and they'll be attached directly to that job.</p>
118→              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job.</p>
119→              <p><strong>Supported formats:</strong> PDF and DOCX attachments are automatically extracted and uploaded.</p>
120→            </div>
121→          </CollapsibleContent>
122→        </Collapsible>
123→      </CardContent>
124→    </Card>
125→  );
126→};
127→
128→export default EmailInboxCard;
