 20→/** Helper: call admin-users edge function with auth */
 21→async function adminCall(body: any) {
 22→  const { data: { session } } = await supabase.auth.getSession();
 23→  const res = await supabase.functions.invoke("admin-users", {
 24→    headers: { Authorization: `Bearer ${session?.access_token}` },
 25→    body,
 26→  });
 27→  if (res.error) throw new Error(res.error.message || "Admin call failed");
 28→  const data = res.data as any;
 29→  if (data?.error) throw new Error(data.error);
 30→  return data;
 31→}
