 33→const EmailSettingsTab = () => {
 34→  const qc = useQueryClient();
 35→  const [search, setSearch] = useState("");
 36→  const [testEmailTo, setTestEmailTo] = useState("");
 37→  const [sendingTest, setSendingTest] = useState(false);
 38→
 39→  // SendGrid config form state
 40→  const [sgApiKey, setSgApiKey] = useState("");
 41→  const [sgFromAddress, setSgFromAddress] = useState("");
 42→  const [sgFromName, setSgFromName] = useState("");
 43→  const [configLoaded, setConfigLoaded] = useState(false);
 44→
 45→  // Global config - fetched via edge function to get all columns including new ones
 46→  const { data: config } = useQuery({
 47→    queryKey: ["admin_config"],
 48→    queryFn: () => adminCall({ action: "get_config" }),
 49→  });
 50→
 51→  // Populate form fields when config loads
 52→  useEffect(() => {
 53→    if (config && !configLoaded) {
