 55→      setSgFromAddress(config.email_from_address || "noreply@rankora.co");
 56→      setSgFromName(config.email_from_name || "Rankora");
 57→      setConfigLoaded(true);
 58→    }
 59→  }, [config, configLoaded]);
 60→
 61→  // Email templates - fetched via edge function
 62→  const { data: templates = [] } = useQuery({
 63→    queryKey: ["email_templates"],
 64→    queryFn: () => adminCall({ action: "get_templates" }),
 65→  });
 66→
 67→  // Helper mutation to update a single config field
 68→  const updateConfig = useMutation({
 69→    mutationFn: (updates: Record<string, any>) =>
 70→      adminCall({ action: "update_config", updates }),
 71→    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin_config"] }),
