117→    onSuccess: () => {
118→      toast.success("SendGrid configuration saved");
119→      qc.invalidateQueries({ queryKey: ["admin_config"] });
120→    },
121→    onError: (e: any) => toast.error(e.message),
122→  });
123→
124→  const updateTemplate = useMutation({
125→    mutationFn: ({ id, subject, body_html }: { id: string; subject: string; body_html: string }) =>
126→      adminCall({ action: "update_template", template_id: id, subject, body_html }),
127→    onSuccess: () => {
