216→      u.email?.toLowerCase().includes(search.toLowerCase()) ||
217→      u.inbox_email?.toLowerCase().includes(search.toLowerCase())
218→  );
219→
220→  const globalEnabled = config?.email_ingestion_enabled ?? true;
