238→
239→        {/* SendGrid Configuration Tab */}
240→        <TabsContent value="sendgrid" className="space-y-6">
241→          <Card>
242→            <CardHeader className="pb-3">
243→              <CardTitle className="text-lg flex items-center gap-2">
244→                <Send className="h-5 w-5" /> SendGrid Configuration
245→              </CardTitle>
246→              <CardDescription>
247→                Configure SendGrid (Twilio) for sending outbound notification emails.
248→              </CardDescription>
249→            </CardHeader>
250→            <CardContent className="space-y-5">
251→              {/* Outbound Email Master Toggle */}
252→              <div className="flex items-center justify-between rounded-lg border border-border p-4">
