254→                  <Label className="text-sm font-medium">Outbound Email</Label>
255→                  <p className="text-xs text-muted-foreground">Enable sending notification emails to users via SendGrid</p>
256→                </div>
257→                <Switch
258→                  checked={outboundEnabled}
259→                  onCheckedChange={(v) => toggleOutbound.mutate(v)}
260→                />
261→              </div>
262→
263→              {/* Status Indicator */}
264→              <div className={`flex items-center gap-2 rounded-lg border p-3 ${hasApiKey && outboundEnabled ? "border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950" : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950"}`}>
265→                {hasApiKey && outboundEnabled ? (
266→                  <>
267→                    <CheckCircle2 className="h-4 w-4 text-green-600" />
268→                    <span className="text-sm text-green-700 dark:text-green-400">SendGrid is configured and active</span>
269→                  </>
