277→                )}
278→              </div>
279→
280→              {/* SendGrid Credentials */}
281→              <div className="space-y-4">
282→                <div className="space-y-2">
283→                  <Label htmlFor="sg-api-key" className="text-sm font-medium flex items-center gap-1.5">
284→                    <Key className="h-3.5 w-3.5" /> SendGrid API Key
285→                  </Label>
286→                  <Input
287→                    id="sg-api-key"
288→                    type="password"
289→                    placeholder="SG.xxxxxxxxxxxxxxxxxxxxxxxx"
290→                    value={configLoaded ? maskedApiKey : ""}
291→                    onChange={(e) => setSgApiKey(e.target.value)}
292→                    className="font-mono text-sm"
293→                  />
294→                  <p className="text-xs text-muted-foreground">
295→                    Get your API key from{" "}
296→                    <a href="https://app.sendgrid.com/settings/api_keys" target="_blank" rel="noopener noreferrer" className="underline text-primary">
297→                      SendGrid Dashboard &gt; Settings &gt; API Keys
298→                    </a>. Requires "Mail Send" permission.
299→                  </p>
300→                </div>
301→
302→                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
303→                  <div className="space-y-2">
304→                    <Label htmlFor="sg-from-email" className="text-sm font-medium">From Email Address</Label>
305→                    <Input
306→                      id="sg-from-email"
307→                      type="email"
308→                      placeholder="noreply@yourdomain.com"
309→                      value={sgFromAddress}
310→                      onChange={(e) => setSgFromAddress(e.target.value)}
311→                    />
312→                    <p className="text-xs text-muted-foreground">Must be a verified sender in SendGrid.</p>
313→                  </div>
314→                  <div className="space-y-2">
315→                    <Label htmlFor="sg-from-name" className="text-sm font-medium">From Name</Label>
316→                    <Input
317→                      id="sg-from-name"
318→                      placeholder="Rankora"
319→                      value={sgFromName}
320→                      onChange={(e) => setSgFromName(e.target.value)}
321→                    />
322→                  </div>
323→                </div>
324→
325→                <Button onClick={() => saveSendGridConfig.mutate()} disabled={saveSendGridConfig.isPending} className="gap-2">
326→                  <Save className="h-4 w-4" />
327→                  {saveSendGridConfig.isPending ? "Saving..." : "Save SendGrid Settings"}
328→                </Button>
329→              </div>
330→
331→              {/* Notification Toggles */}
332→              <div className="space-y-3 pt-2">
333→                <h4 className="text-sm font-medium text-foreground">Notification Types</h4>
334→                <div className="flex items-center justify-between rounded-lg border border-border p-3">
335→                  <div className="space-y-0.5">
336→                    <Label className="text-sm">Ranking Complete</Label>
