  9→async function authenticateAdmin(req: Request) {
 10→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 11→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 12→  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
 13→
 14→  const authHeader = req.headers.get("Authorization");
 15→  if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
 16→
 17→  const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 18→    global: { headers: { Authorization: authHeader } },
 19→  });
 20→  const token = authHeader.replace("Bearer ", "");
 21→  const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
 22→  if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
 23→  const adminUserId = claimsData.claims.sub as string;
 24→
 25→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 26→
 27→  const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", adminUserId);
 28→  if (!roles?.some((r: any) => r.role === "admin")) {
 29→    throw new Error("Admin access required");
 30→  }
 31→
 32→  return { supabase, adminUserId };
 33→}
