 35→serve(async (req) => {
 36→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 37→
 38→  try {
 39→    const { supabase, adminUserId } = await authenticateAdmin(req);
 40→
 41→    let body: any = null;
 42→    try {
 43→      const text = await req.text();
 44→      if (text) body = JSON.parse(text);
 45→    } catch {
 46→      // empty or invalid body — treat as list request
 47→    }
 48→
 49→    const action = body?.action;
 50→
 51→    // ─── Ban / Suspend user ───
 52→    if (action === "ban") {
 53→      const { user_id, banned } = body;
 54→      if (!user_id) throw new Error("user_id required");
 55→      if (banned) {
 56→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "876000h" }); // ~100 years
 57→        if (error) throw error;
 58→      } else {
 59→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "none" });
 60→        if (error) throw error;
 61→      }
 62→      return new Response(JSON.stringify({ success: true }), {
 63→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 64→      });
 65→    }
 66→
 67→    // ─── Get user activity detail ───
 68→    if (action === "activity") {
 69→      const { user_id } = body;
 70→      if (!user_id) throw new Error("user_id required");
 71→
 72→      const [usageRes, jobsRes, resumesRes, paymentsRes] = await Promise.all([
 73→        supabase.from("usage_logs").select("*").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 74→        supabase.from("jobs").select("id, title, status, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 75→        supabase.from("resumes").select("id, filename, status, created_at, job_id").order("created_at", { ascending: false }).limit(100),
 76→        supabase.from("payments").select("id, amount, currency, status, credits_purchased, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 77→      ]);
 78→
 79→      // Filter resumes to only those belonging to user's jobs
 80→      const jobIds = new Set(jobsRes.data?.map((j: any) => j.id) ?? []);
 81→      const userResumes = resumesRes.data?.filter((r: any) => jobIds.has(r.job_id)) ?? [];
 82→
 83→      return new Response(JSON.stringify({
 84→        usage_logs: usageRes.data ?? [],
 85→        jobs: jobsRes.data ?? [],
 86→        resumes: userResumes,
 87→        payments: paymentsRes.data ?? [],
 88→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
 89→    }
 90→
 91→    // ─── GDPR data export ───
 92→    if (action === "gdpr_export") {
 93→      const { user_id } = body;
 94→      if (!user_id) throw new Error("user_id required");
 95→
 96→      const { data: authUser } = await supabase.auth.admin.getUserById(user_id);
 97→      const [profileRes, usageRes, jobsRes, paymentsRes, rolesRes] = await Promise.all([
 98→        supabase.from("profiles").select("*").eq("user_id", user_id),
 99→        supabase.from("usage_logs").select("*").eq("user_id", user_id),
100→        supabase.from("jobs").select("*").eq("user_id", user_id),
101→        supabase.from("payments").select("*").eq("user_id", user_id),
102→        supabase.from("user_roles").select("*").eq("user_id", user_id),
103→      ]);
104→
105→      // Get resumes for user's jobs
106→      const jobIds = jobsRes.data?.map((j: any) => j.id) ?? [];
107→      let resumes: any[] = [];
108→      if (jobIds.length > 0) {
109→        const { data } = await supabase.from("resumes").select("id, filename, status, created_at, candidate_name, source").in("job_id", jobIds);
110→        resumes = data ?? [];
111→      }
112→
113→      const exportData = {
114→        exported_at: new Date().toISOString(),
115→        user: {
116→          id: authUser?.user?.id,
117→          email: authUser?.user?.email,
118→          created_at: authUser?.user?.created_at,
119→          last_sign_in_at: authUser?.user?.last_sign_in_at,
120→        },
121→        profile: profileRes.data?.[0] ?? null,
122→        roles: rolesRes.data ?? [],
123→        jobs: jobsRes.data ?? [],
124→        resumes,
125→        usage_logs: usageRes.data ?? [],
126→        payments: paymentsRes.data ?? [],
127→      };
128→
129→      return new Response(JSON.stringify(exportData), {
130→        headers: { ...corsHeaders, "Content-Type": "application/json" },
131→      });
132→    }
