165→
166→      const updates = body.updates || {};
167→      const setClauses: string[] = [];
168→      const values: any[] = [];
169→      let paramIdx = 1;
170→
171→      for (const [key, val] of Object.entries(updates)) {
172→        if (allowedFields.includes(key)) {
173→          setClauses.push(`${key} = $${paramIdx}`);
174→          values.push(val);
175→          paramIdx++;
176→        }
177→      }
178→
179→      if (setClauses.length === 0) throw new Error("No valid fields to update");
180→
181→      setClauses.push(`updated_at = now()`);
182→      const sql = `UPDATE platform_config SET ${setClauses.join(", ")} WHERE id = (SELECT id FROM platform_config LIMIT 1)`;
183→
184→      const { error } = await supabase.rpc("exec_sql", { query: sql, params: values }).maybeSingle();
185→
186→      // Fallback: if exec_sql RPC doesn't exist, use direct update
187→      if (error) {
188→        // Try direct update via service role (bypasses PostgREST cache for service role)
189→        const { data: configRow } = await supabase.from("platform_config").select("id").limit(1).single();
190→        if (!configRow) throw new Error("No platform_config row found");
191→
192→        const cleanUpdates: any = {};
193→        for (const [key, val] of Object.entries(updates)) {
194→          if (allowedFields.includes(key)) cleanUpdates[key] = val;
195→        }
196→
197→        const { error: updateErr } = await supabase.from("platform_config").update(cleanUpdates).eq("id", configRow.id);
198→        if (updateErr) throw updateErr;
199→      }
200→
201→      return new Response(JSON.stringify({ success: true }), {
202→        headers: { ...corsHeaders, "Content-Type": "application/json" },
203→      });
204→    }
205→
206→    // ─── Get platform config ───
207→    if (action === "get_config") {
208→      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
209→      if (error) throw error;
210→      // Mask the SendGrid API key for security
211→      if (data && (data as any).sendgrid_api_key) {
212→        const key = (data as any).sendgrid_api_key as string;
213→        (data as any).sendgrid_api_key_masked = key.slice(0, 5) + "***" + key.slice(-4);
214→        (data as any).has_sendgrid_key = true;
215→        delete (data as any).sendgrid_api_key;
216→      } else {
217→        (data as any).has_sendgrid_key = false;
218→      }
219→      return new Response(JSON.stringify(data), {
220→        headers: { ...corsHeaders, "Content-Type": "application/json" },
221→      });
222→    }
223→
224→    // ─── Get email templates ───
225→    if (action === "get_templates") {
226→      const { data, error } = await supabase
227→        .from("email_templates")
228→        .select("*")
229→        .order("template_key");
230→      if (error) throw error;
231→      return new Response(JSON.stringify(data), {
232→        headers: { ...corsHeaders, "Content-Type": "application/json" },
233→      });
234→    }
235→
236→    // ─── Update email template ───
237→    if (action === "update_template") {
238→      const { template_id, subject, body_html } = body;
239→      if (!template_id) throw new Error("template_id required");
240→      const { error } = await supabase
241→        .from("email_templates")
242→        .update({ subject, body_html, updated_at: new Date().toISOString() })
243→        .eq("id", template_id);
244→      if (error) throw error;
245→      return new Response(JSON.stringify({ success: true }), {
246→        headers: { ...corsHeaders, "Content-Type": "application/json" },
247→      });
248→    }
249→
250→    // ─── List all users (default) ───
251→    const { data: authUsers } = await supabase.auth.admin.listUsers({ perPage: 1000 });
252→    const { data: profiles } = await supabase.from("profiles").select("*");
253→    const { data: userRoles } = await supabase.from("user_roles").select("*");
254→
255→    const users = authUsers?.users?.map((u: any) => {
256→      const profile = profiles?.find((p: any) => p.user_id === u.id);
257→      const role = userRoles?.find((r: any) => r.user_id === u.id);
258→      return {
259→        id: u.id,
260→        email: u.email,
261→        credits: profile?.credits ?? 0,
262→        plan: profile?.plan ?? "free",
263→        role: role?.role ?? "user",
264→        inbox_email: profile?.inbox_email ?? null,
265→        email_enabled: profile?.email_enabled ?? true,
266→        created_at: u.created_at,
267→        last_sign_in_at: u.last_sign_in_at ?? null,
268→        banned_until: u.banned_until ?? null,
269→      };
270→    }) ?? [];
271→
272→    return new Response(JSON.stringify(users), {
273→      headers: { ...corsHeaders, "Content-Type": "application/json" },
274→    });
275→  } catch (err: unknown) {
276→    const msg = err instanceof Error ? err.message : String(err);
277→    const status = msg === "Admin access required" ? 403 : 500;
278→    return new Response(JSON.stringify({ error: msg }), {
279→      status, headers: { ...corsHeaders, "Content-Type": "application/json" },
280→    });
281→  }
282→});
